import type { CargoItem, Orientation } from '../types/packing'

export function CargoConstraints({ item, onChange }: { item: CargoItem; onChange: (patch: Partial<CargoItem>) => void }) {
  const orientations: Array<[Orientation,string]> = [['standing','立放'],['lying','侧放'],['flat','平放']]
  const allowed = (direction: Orientation) => item.allowedOrientations.includes(direction) && !item.forbiddenOrientations?.includes(direction)
  return <div className="studio-constraints"><h3>装载约束 · 方向 / 承重 / 混装</h3><p>修改作用于当前同源批次；方向名称按该货物原始轴定义。</p>
    <strong>允许摆放方向</strong><div className="studio-constraint-line">{orientations.map(([direction,label]) => <label key={direction}><input type="checkbox" checked={allowed(direction)} onChange={e => {
      const next = e.target.checked ? [...new Set([...item.allowedOrientations,direction])] : item.allowedOrientations.filter(v => v !== direction)
      const forbidden = e.target.checked ? item.forbiddenOrientations?.filter(v => v !== direction) : item.forbiddenOrientations
      if (next.some(v => !forbidden?.includes(v))) onChange({ allowedOrientations: next, forbiddenOrientations: forbidden })
    }} />{label}</label>)}</div>
    <div className="studio-fieldgrid"><label><span>顶部承重 kg（空为未设）</span><input aria-label="货物顶部承重" type="number" min="0" value={item.maxStackWeight ?? ''} onChange={e => { const n = Number(e.target.value); if (e.target.value === '' || Number.isFinite(n) && n >= 0) onChange({ maxStackWeight: e.target.value === '' ? undefined : n }) }} /></label><label><span>上方最多件数（空为未设）</span><input aria-label="货物最大叠放件数" type="number" min="0" step="1" value={item.maxStackCount ?? ''} onChange={e => { const n = Number(e.target.value); if (e.target.value === '' || Number.isInteger(n) && n >= 0) onChange({ maxStackCount: e.target.value === '' ? undefined : n }) }} /></label></div>
    <div className="studio-constraint-checks"><label><input type="checkbox" checked={item.canStackOnTop} onChange={e => onChange({ canStackOnTop: e.target.checked })} />允许顶部承托</label><label><input type="checkbox" checked={item.canOffsetStack} onChange={e => onChange({ canOffsetStack: e.target.checked })} />允许错位叠放</label><label><input type="checkbox" checked={!!item.constraints?.mustBeOnFloor} onChange={e => onChange({ constraints: { ...item.constraints, mustBeOnFloor: e.target.checked } })} />必须落地</label><label><input type="checkbox" checked={!!item.constraints?.supportedItemsLargestFaceDown} onChange={e => onChange({ constraints: { ...item.constraints, supportedItemsLargestFaceDown: e.target.checked } })} />上方货物最大面朝下</label></div>
    <label className="studio-constraint-group">混装组 <input aria-label="货物混装组" placeholder="可选" value={item.constraints?.mixGroup ?? ''} onChange={e => onChange({ constraints: { ...item.constraints, mixGroup: e.target.value || undefined, ...(!e.target.value ? { onlySameMixGroup: false } : {}) } })} /></label><label className="studio-constraint-line"><input type="checkbox" disabled={!item.constraints?.mixGroup?.trim()} checked={!!item.constraints?.onlySameMixGroup} onChange={e => onChange({ constraints: { ...item.constraints, onlySameMixGroup: e.target.checked } })} />只允许同组混装</label>
    <strong>允许水平旋转</strong><div className="studio-constraint-line">{([0,90,180,270] as const).map(angle=><label key={angle}><input type="checkbox" checked={(item.constraints?.horizontalRotations ?? [0,90]).includes(angle)} onChange={e=>{const old = item.constraints?.horizontalRotations ?? [0,90]; const next = e.target.checked ? [...old,angle] : old.filter(v=>v!==angle); if (next.length) onChange({constraints:{...item.constraints,horizontalRotations:next}})}} />{angle}°</label>)}</div>
    <strong>按方向单独限制（可选）</strong><p>方向专用限制优先于通用承重和件数；留空则使用通用值。</p>{orientations.filter(([direction])=>allowed(direction)).map(([direction,label])=><div className="studio-orientation-rule" key={direction}><b>{label}</b><div className="studio-fieldgrid">{([['maxStackWeight','顶部总承重 kg'],['maxStackCount','上方最多件数'],['maxSupportedItemWeight','单件最大重量 kg']] as const).map(([field,title])=><label key={field}><span>{title}</span><input aria-label={`${label}${title}`} type="number" min="0" value={item.constraints?.orientationRules?.[direction]?.[field] ?? ''} onChange={e=>{ const n=Number(e.target.value); if(e.target.value !== '' && (!Number.isFinite(n) || n<0 || field==='maxStackCount' && !Number.isInteger(n))) return; const rules = {...item.constraints?.orientationRules}; const directionRule = {...rules[direction]}; if(e.target.value === '') delete directionRule[field]; else directionRule[field] = n; if (!Object.keys(directionRule).length) delete rules[direction]; else rules[direction] = directionRule; onChange({constraints:{...item.constraints,orientationRules:rules}}) }} /></label>)}</div></div>)}
    <p>方向名称与原始轴的映射：立放 {item.orientationVerticalAxes?.standing ?? 'height'}；侧放 {item.orientationVerticalAxes?.lying ?? 'width'}；平放 {item.orientationVerticalAxes?.flat ?? 'length'}。</p>
  </div>
}
